/**
 * How far back a search for the reading a series was last left at reaches, in
 * widening steps so the common case of a recent reading costs one lookup and a
 * standing level set long ago is still found.
 */
const LOOKBACK_SPANS_IN_MS = [
    36e5, // an hour
    864e5, // a day
    6048e5, // a week
    2592e6, // thirty days
    7776e6, // ninety days
    31536e6, // a year
    39312e6, // fifteen months, as far back as readings are kept
];

/**
 * The last reading a series holds strictly before an instant, however long
 * before it was published. Used to know the level a series was left standing at
 * when a window opens without a reading of its own.
 */
export const readLatestUsageSampleBefore = async ({
    series,
    before,
}: {
    series: UsageSeries;
    before: Date;
}): Promise<UsageSample | undefined> => {
    for (const span of LOOKBACK_SPANS_IN_MS) {
        const samples = await readUsageSamples({
            series,
            startTime: new Date(before.getTime() - span),
            endTime: before,
        });
        if (samples.length) {
            return samples.reduce((latest, sample) =>
                new Date(sample.timestamp).getTime() > new Date(latest.timestamp).getTime() ? sample : latest,
            );
        }
    }
    return undefined;
};
