        case aggregationInterval.month:
            return new Date(Date.UTC(year, month, 1));
        case aggregationInterval.day:
            return new Date(Date.UTC(year, month, day));
        default:
            return new Date(Date.UTC(year, month, day, instant.getUTCHours()));
    }
};

/** The clock aligned edge the step following the one at an edge begins on. */
const nextStepEdge = (edge: Date, step: aggregationInterval): Date => {
    switch (step) {
        case aggregationInterval.month:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth() + 1, 1));
        case aggregationInterval.day:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth(), edge.getUTCDate() + 1));
        default:
            return new Date(edge.getTime() + 36e5);
    }
};

/**
 * The steps a window is made of. Edges sit on the clock, so a step of an hour
 * begins on the hour and a step of a day or a month on the first instant of it,
 * while the first and the last step are clamped to the window so a curve never
 * reaches outside of what was asked for.
 */
export const usageWindowSteps = ({
    startTime,
    endTime,
    step,
}: {
    startTime: string;
    endTime: string;
    step?: aggregationInterval;
}): UsageWindowStep[] => {
    const windowStart = new Date(startTime).getTime();
    const windowEnd = new Date(endTime).getTime();
    if (!(windowEnd > windowStart)) {
        return [];
    }
    const every = step && step !== aggregationInterval.none ? step : DEFAULT_STEP;
    const steps: UsageWindowStep[] = [];
    let edge = stepEdgeOf(new Date(windowStart), every);
    while (edge.getTime() < windowEnd) {
        const next = nextStepEdge(edge, every);
        steps.push({
            startTime: new Date(Math.max(edge.getTime(), windowStart)).toISOString(),
            endTime: new Date(Math.min(next.getTime(), windowEnd)).toISOString(),
        });
        edge = next;
    }
    return steps;
};

/**
 * Whether a dimension is provisioned, meaning a reading sets a level that keeps
 * standing until the next one arrives rather than a one off amount of usage.
 */
const holdsStandingLevel = (dimension: ReadDimensionResponseData): boolean =>
    dimension?.sampleType === SampleType.continious ||
    (!dimension?.sampleType && dimension?.paymentSchedule === PaymentSchedule.upfront);

/** Readings ordered as they happened, oldest first. */
const inOrder = (samples: UsageSample[]): UsageSample[] =>
    [...samples].sort((left, right) => new Date(left.timestamp).getTime() - new Date(right.timestamp).getTime());

/**
 * The curve a set of readings makes over a window's steps. A step a reading
 * landed in holds whatever the dimension's aggregation method makes of the
 * readings in it. A step without a reading of its own carries the level a
 * provisioned dimension was last left standing at, which can have been set
 * however long before the window, and is unused, so zero, for anything else.
 */
const curveOverSteps = ({
    samples,
    steps,
    method,
    standingLevel,
}: {
    samples: UsageSample[];
    steps: UsageWindowStep[];
    method: aggregationMethod;
    standingLevel?: number;
}): UsageResponseDocument[] => {
    const ordered = inOrder(samples);
    let carried = standingLevel;
    let index = 0;
    return steps.map(({ startTime, endTime }) => {
        const stepStart = new Date(startTime).getTime();
        const stepEnd = new Date(endTime).getTime();
        while (index < ordered.length && new Date(ordered[index].timestamp).getTime() < stepStart) {
            carried = ordered[index].value;
            index += 1;
        }
        const readings: number[] = [];
        while (index < ordered.length && new Date(ordered[index].timestamp).getTime() < stepEnd) {
            readings.push(ordered[index].value);
            index += 1;
        }
        let value: number;
        if (readings.length) {
            value = reduceSamples(readings, method);
            carried = readings[readings.length - 1];
        } else {
            value = carried === undefined ? 0 : carried;
        }
        return new UsageDocument({ value: `${value}`, startTime, endTime });
    });
};

/** The level a series was left standing at before a window opened, if any. */
const standingLevelBefore = async ({
    series,
    before,
}: {
    series: UsageSeries;
    before: Date;
}): Promise<number | undefined> => {
    const sample = await readLatestUsageSampleBefore({ series, before });
    return sample === undefined ? undefined : sample.value;
};

/** One published group of a dimension's readings and the curve it makes. */
type PublishedUsageCurve = {
    usage: UsageResponseDocument[] | BasicUsageDocument[];
    metadataGroup?: Record<string, string>;
};

