        [usageData]: async ({
            businessID,
            startTime,
            endTime,
            dimension,
            customerId,
        }: SingleUsageEvent): Promise<PublishedUsageCurve[]> => {
            const {
                dimensionId,
                aggregationInterval: argumentAgg,
                aggregationMethod: argumentAggregationMethod,
                tiersGroupByMetadata,
            } = dimension as ReadDimensionResponseData;
            const published = await listUsageSeries({ businessID, customerId, dimensionId });
            const windowStart = new Date(startTime);
            const windowEnd = new Date(endTime);

            if (argumentAgg === aggregationInterval.none) {
                const unAggregatedResults: BasicUsageDocument[] = [];
                for (const series of published) {
                    const samples = await readUsageSamples({ series, startTime: windowStart, endTime: windowEnd });
                    const metadata = metadataOf(series);
                    samples.forEach(({ timestamp, value }) => {
                        unAggregatedResults.push({ timestamp, recordValue: value.toString(), metadata });
                    });
                }
                return [{ usage: unAggregatedResults }];
            }

            const steps = usageWindowSteps({ startTime, endTime, step: argumentAgg });
            const provisioned = holdsStandingLevel(dimension as ReadDimensionResponseData);

            /*
             * A dimension priced by metadata group is reported a group at a
             * time, so every group a customer has published keeps a curve of
             * its own.
             */
            if (tiersGroupByMetadata && tiersGroupByMetadata.length > 0) {
                const grouped: PublishedUsageCurve[] = [];
                for (const series of published) {
                    const samples = await readUsageSamples({ series, startTime: windowStart, endTime: windowEnd });
                    const metadataGroup = metadataOf(series);
                    const standingLevel = provisioned
                        ? await standingLevelBefore({ series, before: windowStart })
                        : undefined;
                    grouped.push({
                        usage: curveOverSteps({
                            samples,
                            steps,
                            method: argumentAggregationMethod,
                            standingLevel,
                        }),
                        ...(Object.keys(metadataGroup).length ? { metadataGroup } : {}),
                    });
                }
                if (grouped.length) {
                    return grouped;
                }
                /* Nothing published yet still answers with every step of the window. */
                return [{ usage: curveOverSteps({ samples: [], steps, method: argumentAggregationMethod }) }];
            }

            const readings: UsageSample[] = [];
            const priorLevels: number[] = [];
            for (const series of published) {
                const samples = await readUsageSamples({ series, startTime: windowStart, endTime: windowEnd });
                samples.forEach((sample) => readings.push(sample));
                if (provisioned) {
                    const level = await standingLevelBefore({ series, before: windowStart });
                    if (level !== undefined) {
                        priorLevels.push(level);
                    }
                }
            }
            return [
                {
                    usage: curveOverSteps({
                        samples: readings,
                        steps,
                        method: argumentAggregationMethod,
                        standingLevel: priorLevels.length
                            ? reduceSamples(priorLevels, argumentAggregationMethod)
