    aggregationInterval,
    aggregationMethod,
    PaymentSchedule,
    SampleType,
} from '../dimensions/dto/create-dimension.dto.js';
import { USAGE_METRIC_NAME, USAGE_NAMESPACE } from '../utils/aws/cloudwatchUsage.js';

const businessID = 'curve-check-business';
const cw = new CloudWatchClient({ region: process.env.AWS_REGION });

const publish = async ({ customerId, dimensionId, readings, metadata = {} }) => {
    await cw.send(
        new PutMetricDataCommand({
            Namespace: USAGE_NAMESPACE,
            MetricData: readings.map(({ timestamp, value }) => ({
                MetricName: USAGE_METRIC_NAME,
                Timestamp: new Date(timestamp),
                Value: value,
                Dimensions: [
                    { Name: 'BusinessId', Value: businessID },
                    { Name: 'CustomerId', Value: customerId },
                    { Name: 'DimensionId', Value: dimensionId },
                    ...Object.keys(metadata).map((key) => ({ Name: `Metadata_${key}`, Value: metadata[key] })),
                ],
            })),
        }),
    );
};

const aggregate = ({ customerId, dimension, startTime, endTime }) =>
    UsageAggregationEvent.getAggregateUsageForDimension({
