            readings: [
                { timestamp: '2024-01-01T00:10:00Z', value: 5 },
                { timestamp: '2024-01-01T00:20:00Z', value: 7 },
                { timestamp: '2024-01-01T02:30:00Z', value: 9 },
            ],
        });
        const res = await aggregate({
            customerId,
            startTime: '2024-01-01T00:05:00Z',
            endTime: '2024-01-01T03:20:00Z',
