                dimensionId,
                aggregationInterval: aggregationInterval.hour,
                aggregationMethod: aggregationMethod.sum,
            },
        });
        console.log(JSON.stringify(res, null, 1));
        expect(res.length).toBe(1);
        expect((res[0] as never as { usage: unknown[] }).usage).toEqual([
            { value: '12', startTime: '2024-01-01T00:05:00.000Z', endTime: '2024-01-01T01:00:00.000Z' },
            { value: '0', startTime: '2024-01-01T01:00:00.000Z', endTime: '2024-01-01T02:00:00.000Z' },
            { value: '9', startTime: '2024-01-01T02:00:00.000Z', endTime: '2024-01-01T03:00:00.000Z' },
            { value: '0', startTime: '2024-01-01T03:00:00.000Z', endTime: '2024-01-01T03:20:00.000Z' },
        ]);
    });

    it('carries a provisioned level, set long before the window, through quiet steps', async () => {
        const customerId = randomUUID();
        const dimensionId = randomUUID();
        await publish({
            customerId,
