/**
 * The steps a window is made of. Edges sit on the clock, so a step of an hour
 * begins on the hour and a step of a day or a month on the first instant of it,
 * while the first and the last step are clamped to the window so a curve never
 * reaches outside of what was asked for.
 */
export const usageWindowSteps = ({
    startTime,
    endTime,
    step,
}: {
    startTime: string;
    endTime: string;
    step?: aggregationInterval;
}): UsageWindowStep[] => {
    const windowStart = new Date(startTime).getTime();
    const windowEnd = new Date(endTime).getTime();
    if (!(windowEnd > windowStart)) {
        return [];
    }
    const every = step && step !== aggregationInterval.none ? step : DEFAULT_STEP;
    const steps: UsageWindowStep[] = [];
    let edge = stepEdgeOf(new Date(windowStart), every);
    while (edge.getTime() < windowEnd) {
        const next = nextStepEdge(edge, every);
        steps.push({
            startTime: new Date(Math.max(edge.getTime(), windowStart)).toISOString(),
            endTime: new Date(Math.min(next.getTime(), windowEnd)).toISOString(),
        });
        edge = next;
    }
    return steps;
};

